function openMenuOverlay() {
	  if (!menuOverlay) return;
	  menuOverlay.classList.add('show');
	  document.body.style.overflow = 'hidden';   // stop background scroll
	  document.body.classList.add('menu-open');  // 👈 NEW: flag that menu is open
	}

